 function updateChange(){let total=cart.reduce((a,c)=>a+(c.price+(c.addons||[]).reduce((n,x)=>n+Number(x.price||0),0))*c.qty,0),received=Number(document.getElementById('received').value||0);document.getElementById('change').textContent=money(Math.max(0,received-total))}
