 document.getElementById('checkout').onclick=()=>{if(!cart.length)return notify('Add a product first.');let total=cart.reduce((a,c)=>a+(c.price+(c.addons||[]).reduce((n,x)=>n+Number(x.price||0),0))*c.qty,0),received=Number(document.getElementById('received').value||0),payment=document.getElementById('payment').value;if(payment==='Cash'&&received<total)return notify('Amount received is less than total.');if((db.employees||[]).some(e=>e.active!==false)&&!document.getElementById('cashier').value)return notify('Select the cashier for this sale.');let cashierId=Number(document.getElementById('cashier').value||0),cashier=(db.employees||[]).find(e=>e.id===cashierId);let sale={id:Date.now(),date:new Date().toISOString(),cashierId:cashier?cashier.id:null,cashierName:cashier?cashier.name:'Unassigned',items:cart.map(c=>({...c,addons:(c.addons||[]).map(a=>({...a})),lineTotal:(c.price+(c.addons||[]).reduce((n,a)=>n+Number(a.price||0),0))*c.qty})),customerName:document.getElementById('customerName').value.trim(),loyaltyCustomerId:selectedLoyaltyId,orderRequest:document.getElementById('orderRequest').value.trim(),total,cost:cart.reduce((a,c)=>a+c.cost*c.qty,0),payment,received:payment==='Cash'?received:total,change:payment==='Cash'?received-total:0};db.sales.push(sale);if(selectedLoyaltyId){const lc=(db.loyaltyCustomers||[]).find(c=>c.id===selectedLoyaltyId);if(lc){lc.stamps=Number(lc.stamps||0)+1;lc.visits=Number(lc.visits||0)+1;lc.totalSpent=Number(lc.totalSpent||0)+total;lc.updatedAt=sale.date;(db.loyaltyHistory=db.loyaltyHistory||[]).push({id:Date.now(),customerId:lc.id,type:'stamp',stamps:1,saleId:sale.id,date:sale.date,note:'Earned from order #'+sale.id,total});sale.loyaltyCustomerName=lc.name;sale.loyaltyStampsEarned=1;}}save();cart=[];lastReceipt=sale;renderCart();notify('Sale saved. Printing receipt…');printReceipt(sale)};
